package com.sam.syncflow;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.*;import android.graphics.Color;import androidx.core.view.WindowCompat;import androidx.core.content.ContextCompat;import androidx.media3.common.*;import androidx.media3.session.*;import com.google.common.util.concurrent.ListenableFuture;
public class MainActivity extends Activity{
 static final int PICK=42;androidx.media3.session.MediaController controller;ListenableFuture<androidx.media3.session.MediaController> future;TextView track,state;SharedPreferences prefs;
 public void onCreate(Bundle b){super.onCreate(b);WindowCompat.setDecorFitsSystemWindows(getWindow(),true);getWindow().setStatusBarColor(0xff0a0c12);getWindow().setNavigationBarColor(0xff0a0c12);prefs=getSharedPreferences("syncflow",MODE_PRIVATE);
 ScrollView sc=new ScrollView(this);sc.setBackgroundColor(0xff0a0c12);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(28),dp(22),dp(24));sc.addView(root);setContentView(sc);
 root.addView(txt("SYNC / LOCAL AUDIO",12,0xffff705c));TextView title=txt("Sync Flow",34,Color.WHITE);title.setPadding(0,dp(8),0,dp(2));root.addView(title);root.addView(txt("Your music. Your device. Offline.",15,0xffa5afc2));
 LinearLayout art=new LinearLayout(this);art.setGravity(17);art.setOrientation(1);art.setBackgroundColor(0xff1e1b2b);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(190));ap.topMargin=dp(26);root.addView(art,ap);art.addView(txt("〰  ♪  〰",40,0xffff705c));
 track=txt("No track selected",20,Color.WHITE);track.setPadding(0,dp(22),0,dp(4));root.addView(track);state=txt("Choose an audio file to begin.",13,0xffa5afc2);root.addView(state);
 Button pick=btn("＋ Choose local audio");pick.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("audio/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,PICK);});root.addView(pick);
 LinearLayout controls=new LinearLayout(this);Button play=btn("Play / Pause");play.setOnClickListener(v->{if(controller==null){state.setText("Connecting to playback service…");return;}if(controller.getPlaybackState()==Player.STATE_IDLE)controller.prepare();if(controller.isPlaying())controller.pause();else controller.play();});controls.addView(play,new LinearLayout.LayoutParams(0,-2,1));Button stop=btn("Stop");stop.setOnClickListener(v->{if(controller!=null)controller.stop();state.setText("Stopped");});controls.addView(stop,new LinearLayout.LayoutParams(0,-2,1));root.addView(controls);
 root.addView(txt("Prototype: native Media3 playback + Android media session. Full library, playlists and database come after this playback path is proven.",13,0xff919db2));
 if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=0)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},7);connect();}
 void connect(){SessionToken token=new SessionToken(this,new ComponentName(this,PlaybackService.class));future=new androidx.media3.session.MediaController.Builder(this,token).buildAsync();future.addListener(()->{try{controller=future.get();controller.addListener(new Player.Listener(){public void onIsPlayingChanged(boolean p){state.setText(p?"Playing • background playback enabled":"Ready • paused");}public void onMediaItemTransition(MediaItem i,int r){if(i!=null&&i.localConfiguration!=null)track.setText(i.mediaMetadata.title!=null?i.mediaMetadata.title.toString():i.localConfiguration.uri.getLastPathSegment());}});String last=prefs.getString("last_uri",null);if(last!=null){controller.setMediaItem(MediaItem.fromUri(Uri.parse(last)));controller.prepare();track.setText("Last selected audio");state.setText("Restored last selected URI. Press Play.");}}catch(Exception e){state.setText("Playback connection failed: "+e.getClass().getSimpleName());}},ContextCompat.getMainExecutor(this));}
 protected void onActivityResult(int r,int code,Intent d){super.onActivityResult(r,code,d);if(r==PICK&&code==RESULT_OK&&d!=null&&d.getData()!=null){Uri u=d.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}prefs.edit().putString("last_uri",u.toString()).apply();if(controller!=null){controller.setMediaItem(MediaItem.fromUri(u));controller.prepare();controller.play();track.setText(u.getLastPathSegment());state.setText("Loaded local audio • attempting playback");}else state.setText("Audio selected; connecting to playback service.");}}
 protected void onDestroy(){if(future!=null)androidx.media3.session.MediaController.releaseFuture(future);controller=null;super.onDestroy();}
 TextView txt(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;}Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}
}